/**
 * Slot holds (PRD-031, STORY-031-2): a customer holds a slot for 15 minutes while they finish checkout. Holds are
 * swept once a minute: releaseAt(heldAt) is when a hold's slot goes back to the pool.
 */
export const HOLD_MS = 15 * 60 * 1000;
export const SWEEP_MS = 60 * 1000;

/** When the slot held at `heldAt` (ms) is back in the pool: at the first sweep after the hold ends. */
export const releaseAt = (heldAt) => heldAt + HOLD_MS + SWEEP_MS;

/** The holds whose slots are back in the pool at `now`. */
export const released = (holds, now) => holds.filter((h) => !h.paid && releaseAt(h.heldAt) <= now);

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { HOLD_MS, releaseAt, released } from '../slot-hold.js';

// TC-031-2-1: Given a slot is held, when 15 minutes pass without payment, then the slot returns to the pool within 5 seconds.
test('TC-031-2-1: the slot returns to the pool within 5 seconds', () => {
  const heldAt = 0;
  assert.ok(releaseAt(heldAt) - (heldAt + HOLD_MS) <= 5000, `released ${(releaseAt(heldAt) - HOLD_MS) / 1000} s after the hold ends`);
});

test('a paid hold is never released', () => {
  assert.deepEqual(released([{ heldAt: 0, paid: true }], HOLD_MS * 2), []);
});
